describe('Multi-Step Form Navigation', () => {
  beforeEach(() => {
    cy.visit('/multi-step-form');
  });

  it('should navigate back to previous step without losing data', () => {
    // Step 1: Fill in Step 1 fields
    cy.get('[data-testid="step-1-name-input"]').type('John Doe');
    cy.get('[data-testid="step-1-email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="step-1-submit-button"]').click();

    // Verify Step 2 is now visible
    cy.get('[data-testid="step-2-title"]').should('be.visible');

    // Step 2: Fill in Step 2 fields
    cy.get('[data-testid="step-2-address-input"]').type('123 Main St');
    cy.get('[data-testid="step-2-city-input"]').type('Anytown');
    cy.get('[data-testid="step-2-state-select"]').select('CA');
    cy.get('[data-testid="step-2-zip-code-input"]').type('12345');

    // Verify Step 3 is now visible
    cy.get('[data-testid="step-3-title"]').should('be.visible');

    // Step 3: Fill in Step 3 fields
    cy.get('[data-testid="step-3-phone-input"]').type('555-1234');
    cy.get('[data-testid="step-3-confirm-button"]').click();

    // Verify form submission button is visible
    cy.get('[data-testid="submit-form-button"]').should('be.visible');

    // Navigate back to Step 2
    cy.get('[data-testid="back-button"]').click();

    // Verify Step 2 is still visible
    cy.get('[data-testid="step-2-title"]').should('be.visible');

    // Verify Step 2 data is still present
    cy.get('[data-testid="step-2-address-input"]').should('have.value', '123 Main St');
    cy.get('[data-testid="step-2-city-input"]').should('have.value', 'Anytown');

    // Verify Step 1 data is still present
    cy.get('[data-testid="step-1-name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="step-1-email-input"]').should('have.value', 'john.doe@example.com');

    // Verify Step 3 data is still present
    cy.get('[data-testid="step-3-phone-input"]').should('have.value', '555-1234');

    // Verify form submission button is still visible
    cy.get('[data-testid="submit-form-button"]').should('be.visible');
  });

  it('should handle navigation to previous step when form is not fully completed', () => {
    // Step 1: Fill in Step 1 fields
    cy.get('[data-testid="step-1-name-input"]').type('Jane Smith');
    cy.get('[data-testid="step-1-email-input"]').type('jane.smith@example.com');

    // Verify Step 2 is now visible
    cy.get('[data-testid="step-2-title"]').should('be.visible');

    // Step 2: Attempt to navigate back before completing Step 2
    cy.get('[data-testid="back-button"]').click();

    // Verify Step 1 is still visible
    cy.get('[data-testid="step-1-title"]').should('be.visible');

    // Verify Step 2 data is still present
    cy.get('[data-testid="step-2-address-input"]').should('have.value', '');

    // Verify Step 3 is still visible
    cy.get('[data-testid="step-3-title"]').should('be.visible');

    // Verify form submission button is still visible
    cy.get('[data-testid="submit-form-button"]').should('be.visible');
  });
});
